1	/**
2	 * HR Module — People operations for the Polyglot agent factory.
3	 *
4	 * Exposes operations that Cadence, Roster, and Witness execute via their
5	 * agent .md prompts, and that the /hr UI calls directly.
6	 *
7	 * Depends on:
8	 *   - src/org.js       — registry + departments source of truth
9	 *   - src/experience.js — level/YoE/skills computation
10	 *
11	 * Owned data paths (all under ~/.claude/org/):
12	 *   - reviews/YYYY-WW.json         — weekly Cadence review files
13	 *   - reviews/latest.md            — human-readable latest summary for Rex
14	 *   - witness-log.jsonl            — append-only accountability log
15	 *   - daily-scores.jsonl           — per-agent daily accountability scores
16	 *   - recommendations.json         — current Witness PIP/promotion candidates
17	 *   - training-queue.json          — pending curriculum per agent
18	 *   - capability-gaps.jsonl        — append-only log of detected gaps
19	 *   - antipattern-signatures.json  — detection rules
20	 *   - onboarding/<agent>.json      — probationary checklists for new hires
21	 *   - playbooks/onboarding.md      — standard onboarding steps
22	 *   - playbooks/pip.md             — PIP protocol
23	 */
24	
25	const fs = require('fs');
26	const path = require('path');
27	const os = require('os');
28	const dbModule = require('./db');
29	
30	const HOME = os.homedir();
31	const ORG_DIR = path.join(HOME, '.claude', 'org');
32	const REVIEWS_DIR = path.join(ORG_DIR, 'reviews');
33	const ONBOARDING_DIR = path.join(ORG_DIR, 'onboarding');
34	const PLAYBOOKS_DIR = path.join(ORG_DIR, 'playbooks');
35	
36	const WITNESS_LOG = path.join(ORG_DIR, 'witness-log.jsonl');
37	const DAILY_SCORES = path.join(ORG_DIR, 'daily-scores.jsonl');
38	const RECOMMENDATIONS = path.join(ORG_DIR, 'recommendations.json');
39	const TRAINING_QUEUE = path.join(ORG_DIR, 'training-queue.json');
40	const CAPABILITY_GAPS = path.join(ORG_DIR, 'capability-gaps.jsonl');
41	const ANTIPATTERN_SIGS = path.join(ORG_DIR, 'antipattern-signatures.json');
42	const SKILL_INDEX = path.join(ORG_DIR, 'skill-index.json');
43	
44	// ──────────────────────────────────────────────────────────────────────────
45	//  File helpers
46	// ──────────────────────────────────────────────────────────────────────────
47	
48	function ensureDir(dir) {
49	  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
50	}
51	
52	function readJson(filePath, fallback) {
53	  try {
54	    if (!fs.existsSync(filePath)) return fallback;
55	    return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
56	  } catch {
57	    return fallback;
58	  }
59	}
60	
61	function writeJson(filePath, data) {
62	  ensureDir(path.dirname(filePath));
63	  const tmp = filePath + '.tmp';
64	  fs.writeFileSync(tmp, JSON.stringify(data, null, 2));
65	  fs.renameSync(tmp, filePath);
66	}
67	
68	function appendJsonl(filePath, obj) {
69	  ensureDir(path.dirname(filePath));
70	  fs.appendFileSync(filePath, JSON.stringify(obj) + '\n');
71	}
72	
73	// Compact a JSONL file when it exceeds maxLines — keep only the most recent entries.
74	// Archives the full file to <file>.archive-<date> before truncating.
75	function compactJsonlIfNeeded(filePath, maxLines) {
76	  try {
77	    if (!fs.existsSync(filePath)) return;
78	    const content = fs.readFileSync(filePath, 'utf-8');
79	    const lines = content.split('\n').filter(Boolean);
80	    if (lines.length <= maxLines) return;
81	    // Archive first
82	    const archivePath = filePath + '.archive-' + new Date().toISOString().slice(0, 10);
83	    try { fs.renameSync(filePath, archivePath); } catch {}
84	    // Write trimmed file (most recent entries)
85	    const trimmed = lines.slice(-Math.floor(maxLines * 0.8)).join('\n') + '\n';
86	    const tmp = filePath + '.tmp';
87	    fs.writeFileSync(tmp, trimmed, 'utf-8');
88	    fs.renameSync(tmp, filePath);
89	  } catch {}
90	}
91	
92	function readJsonl(filePath) {
93	  try {
94	    if (!fs.existsSync(filePath)) return [];
95	    return fs
96	      .readFileSync(filePath, 'utf-8')
97	      .split('\n')
98	      .filter(Boolean)
99	      .map((l) => { try { return JSON.parse(l); } catch { return null; } })
100	      .filter(Boolean);
101	  } catch {
102	    return [];
103	  }
104	}
105	
106	function currentIsoWeek(date = new Date()) {
107	  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
108	  const dayNum = d.getUTCDay() || 7;
109	  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
110	  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
111	  const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
112	  return `${d.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
113	}
