115	// ──────────────────────────────────────────────────────────────────────────
116	//  Registry views
117	// ──────────────────────────────────────────────────────────────────────────
118	
119	function getRegistry(orgModule) {
120	  const reg = orgModule.loadRegistry();
121	  const agents = Object.values(reg.agents || {});
122	  // Sort: by department, then by level desc, then by name
123	  agents.sort((a, b) => {
124	    if (a.department !== b.department) return (a.department || '').localeCompare(b.department || '');
125	    if ((b.level || 0) !== (a.level || 0)) return (b.level || 0) - (a.level || 0);
126	    return a.id.localeCompare(b.id);
127	  });
128	  return {
129	    version: reg.version || 1,
130	    updatedAt: reg.updatedAt,
131	    total: agents.length,
132	    agents,
133	  };
134	}
135	
136	function getAgentProfile(orgModule, agentId) {
137	  const record = orgModule.findAgent(agentId);
138	  if (!record) return null;
139	  // Enrich with direct reports + manager
140	  const reports = orgModule.findDirectReports(agentId);
141	  return {
142	    ...record,
143	    directReports: reports.map((r) => ({ id: r.id, title: r.title, level: r.level })),
144	  };
145	}
