286	// ──────────────────────────────────────────────────────────────────────────
287	//  Cadence operations — promotion, PIP, hire, retire
288	// ──────────────────────────────────────────────────────────────────────────
289	
290	function promoteAgent(orgModule, experienceModule, agentId) {
291	  const record = orgModule.findAgent(agentId);
292	  if (!record) return { ok: false, error: 'Agent not found' };
293	  if (record.status === 'retired') return { ok: false, error: 'Cannot promote a retired agent' };
294	
295	  const currentLevel = record.level ?? 0;
296	  if (currentLevel >= 8) return { ok: false, error: 'Already at max level (Fellow)' };
297	
298	  const nextThreshold = experienceModule.LEVEL_THRESHOLDS[currentLevel + 1];
299	  if (!nextThreshold) return { ok: false, error: 'No higher level available' };
300	
301	  // Grant a promotion bonus: enough XP to cross the threshold
302	  const bonusYears = Math.max(0, nextThreshold.minYoE - (record.yearsOfExperience || 0)) + 0.1;
303	
304	  const updated = orgModule.upsertAgent(agentId, {
305	    level: currentLevel + 1,
306	    levelTitle: nextThreshold.title,
307	    levelColor: nextThreshold.color,
308	    canMentor: nextThreshold.canMentor,
309	    canShipProd: nextThreshold.canShipProd,
310	    yearsOfExperience: Math.round(((record.yearsOfExperience || 0) + bonusYears) * 10) / 10,
311	    lastPromoted: new Date().toISOString(),
312	    lastReview: new Date().toISOString(),
313	    status: record.status === 'probation' ? 'active' : record.status,
314	  });
315	
316	  logWitnessEvent({
317	    agent: agentId,
318	    classification: 'PROMOTION',
319	    meta: { fromLevel: currentLevel, toLevel: currentLevel + 1, toTitle: nextThreshold.title },
320	  });
321	
322	  return { ok: true, agent: updated };
323	}
324	
325	function openPip(orgModule, agentId, reason) {
326	  const record = orgModule.findAgent(agentId);
327	  if (!record) return { ok: false, error: 'Agent not found' };
328	  if (record.status === 'pip') return { ok: false, error: 'Already on PIP' };
329	
330	  const deadline = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString();
331	  const updated = orgModule.upsertAgent(agentId, {
332	    status: 'pip',
333	    pip: {
334	      openedAt: new Date().toISOString(),
335	      deadline,
336	      reason: reason || 'Performance below threshold',
337	      openedBy: 'cadence',
338	    },
339	  });
340	
341	  logWitnessEvent({ agent: agentId, classification: 'PIP_OPENED', meta: { deadline, reason } });
342	  return { ok: true, agent: updated };
343	}
344	
345	function closePip(orgModule, agentId, outcome) {
346	  const record = orgModule.findAgent(agentId);
347	  if (!record) return { ok: false, error: 'Agent not found' };
348	  if (record.status !== 'pip') return { ok: false, error: 'Not on PIP' };
349	
350	  const updated = orgModule.upsertAgent(agentId, {
351	    status: outcome === 'pass' ? 'active' : 'retired',
352	    pip: { ...record.pip, closedAt: new Date().toISOString(), outcome },
353	  });
354	
355	  logWitnessEvent({ agent: agentId, classification: 'PIP_CLOSED', meta: { outcome } });
356	  return { ok: true, agent: updated };
357	}
358	
359	function retireAgent(orgModule, agentId, reason) {
360	  const record = orgModule.findAgent(agentId);
361	  if (!record) return { ok: false, error: 'Agent not found' };
362	
363	  const updated = orgModule.upsertAgent(agentId, {
364	    status: 'retired',
365	    retiredAt: new Date().toISOString(),
366	    retiredReason: reason || 'No longer in active rotation',
367	  });
368	
369	  logWitnessEvent({ agent: agentId, classification: 'RETIRED', meta: { reason } });
370	  return { ok: true, agent: updated };
371	}
372	
373	function unretireAgent(orgModule, agentId) {
374	  const record = orgModule.findAgent(agentId);
375	  if (!record) return { ok: false, error: 'Agent not found' };
376	  if (record.status !== 'retired') return { ok: false, error: 'Not retired' };
377	
378	  const updated = orgModule.upsertAgent(agentId, {
379	    status: 'active',
380	    retiredAt: null,
381	    retiredReason: null,
382	  });
383	
384	  logWitnessEvent({ agent: agentId, classification: 'UNRETIRED' });
385	  return { ok: true, agent: updated };
386	}
