388	// ──────────────────────────────────────────────────────────────────────────
389	//  Hire — register a new agent + start probationary period
390	// ──────────────────────────────────────────────────────────────────────────
391	
392	function hireAgent(orgModule, { id, name, department, phase, reportsTo, title, tier, role, description }) {
393	  if (!id || !department) return { ok: false, error: 'id and department are required' };
394	
395	  const existing = orgModule.findAgent(id);
396	  if (existing) return { ok: false, error: 'Agent already exists' };
397	
398	  const now = new Date().toISOString();
399	  const record = orgModule.upsertAgent(id, {
400	    id,
401	    name: name || id,
402	    description: description || '',
403	    department,
404	    phase: phase || null,
405	    reportsTo: reportsTo || 'cadence',
406	    title: title || 'New Hire',
407	    tier: tier || 'engineer',
408	    role: role || null,
409	    hiredAt: now,
410	    status: 'probation',
411	    level: 0,
412	    levelTitle: 'Trainee',
413	    yearsOfExperience: 0,
414	    experiencePoints: 0,
415	  });
416	
417	  // Create onboarding checklist
418	  const checklistPath = path.join(ONBOARDING_DIR, `${id}.json`);
419	  writeJson(checklistPath, {
420	    agent: id,
421	    hiredAt: now,
422	    stage: 'probation',
423	    runsRequired: 10,
424	    runsCompleted: 0,
425	    steps: [
426	      { id: 'create_md', done: false, label: 'Agent .md file exists on disk' },
427	      { id: 'load_memory', done: false, label: 'Memory brain loaded into first run' },
428	      { id: 'shadow_3', done: false, label: 'First 3 runs shadowed by senior agent' },
429	      { id: 'independent_7', done: false, label: '7 independent runs with Witness watching' },
430	      { id: 'probation_review', done: false, label: 'Cadence probationary review' },
431	    ],
432	    createdAt: now,
433	  });
434	
435	  logWitnessEvent({ agent: id, classification: 'HIRED', meta: { department, reportsTo } });
436	  return { ok: true, agent: record };
437	}
