443	function getTrainingQueue() {
444	  return dbModule.getTrainingQueue();
445	}
446	
447	function queueTraining({ agent, skill, reason, priority = 'medium' }) {
448	  const queue = getTrainingQueue();
449	  queue.items = queue.items || [];
450	  queue.items.push({
451	    id: `train-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
452	    agent,
453	    skill,
454	    reason,
455	    priority,
456	    status: 'pending',
457	    queuedAt: new Date().toISOString(),
458	  });
459	  queue.updatedAt = new Date().toISOString();
460	  dbModule.saveTrainingQueue(queue);
461	  return queue;
462	}
463	
464	function completeTraining(itemId, outcome = 'passed') {
465	  const queue = getTrainingQueue();
466	  const item = (queue.items || []).find((i) => i.id === itemId);
467	  if (!item) return { ok: false, error: 'Item not found' };
468	  item.status = outcome === 'passed' ? 'completed' : 'failed';
469	  item.completedAt = new Date().toISOString();
470	  queue.updatedAt = new Date().toISOString();
471	  dbModule.saveTrainingQueue(queue);
472	  return { ok: true, item };
473	}
