475	// ──────────────────────────────────────────────────────────────────────────
476	//  Capability gap detection
477	// ──────────────────────────────────────────────────────────────────────────
478	
479	/**
480	 * Given a brief (natural language task description), find out if the
481	 * current roster can handle it. Uses simple keyword matching against
482	 * each agent's skill vector from registry.json.
483	 */
484	function detectCapabilityGap(orgModule, brief, requiredSkillsHint = []) {
485	  const registry = orgModule.loadRegistry();
486	  const agents = Object.values(registry.agents || {})
487	    .filter((a) => a.status === 'active' || a.status === 'probation');
488	
489	  // Infer required skills from brief text if not explicitly given
490	  const inferredSkills = new Set(requiredSkillsHint);
491	  const briefLower = (brief || '').toLowerCase();
492	  const SKILL_HINTS = {
493	    react: ['react', 'component', 'frontend', 'ui'],
494	    typescript: ['typescript', 'ts'],
495	    nextjs: ['next.js', 'app router'],
496	    supabase: ['supabase', 'postgres', 'rls'],
497	    shopify: ['shopify', 'storefront', 'polaris'],
498	    billing: ['stripe', 'billing', 'subscription', 'payment', 'dodo'],
499	    auth: ['auth', 'oauth', 'session', 'login', 'sign in'],
500	    testing: ['test', 'vitest', 'playwright'],
501	    design: ['design', 'figma', 'ui/ux'],
502	    seo: ['seo', 'sitemap', 'meta'],
503	    deployment: ['deploy', 'railway', 'docker'],
504	    ai: ['llm', 'gpt', 'claude', 'prompt'],
505	    marketing: ['landing', 'copy', 'funnel', 'email'],
506	    research: ['validate', 'icp', 'interview', 'market'],
507	    debugging: ['bug', 'fix', 'error', 'crash'],
508	    architecture: ['architecture', 'system design', 'scalab'],
509	  };
510	  for (const [skill, hints] of Object.entries(SKILL_HINTS)) {
511	    if (hints.some((h) => briefLower.includes(h))) inferredSkills.add(skill);
512	  }
513	
514	  const required = [...inferredSkills];
515	  if (required.length === 0) {
516	    return {
517	      canHandle: true,
518	      confidence: 0.5,
519	      bestMatches: [],
520	      gaps: [],
521	      recommendation: 'proceed',
522	      note: 'No specific skills inferred from brief',
523	      inferredSkills: [],
524	    };
525	  }
526	
527	  // Score each agent against required skills
528	  const scored = agents.map((a) => {
529	    const skills = a.skills || {};
530	    let totalScore = 0;
531	    const matched = [];
532	    const missing = [];
533	    for (const req of required) {
534	      const s = skills[req]?.score || 0;
535	      if (s > 0) matched.push({ skill: req, score: s });
536	      else missing.push(req);
537	      totalScore += s;
538	    }
539	    return {
540	      agent: a.id,
541	      title: a.title,
542	      level: a.level,
543	      score: Math.round((totalScore / required.length) * 100) / 100,
544	      matched,
545	      missing,
546	    };
547	  });
548	
549	  scored.sort((a, b) => b.score - a.score);
550	  const bestMatches = scored.slice(0, 3);
551	
552	  // Determine gap + recommendation
553	  const topScore = bestMatches[0]?.score || 0;
554	  const allMissing = required.filter((r) => !scored.some((s) => s.matched.find((m) => m.skill === r && m.score >= 0.4)));
555	  const canHandle = topScore >= 0.7 && allMissing.length === 0;
556	
557	  let recommendation;
558	  if (canHandle) recommendation = 'proceed';
559	  else if (topScore >= 0.4) recommendation = `train-${bestMatches[0].agent}`;
560	  else recommendation = 'hire';
561	
562	  // Log the gap
563	  dbModule.appendCapabilityGap({
564	    t: new Date().toISOString(),
565	    brief: brief.slice(0, 200),
566	    inferredSkills: required,
567	    gaps: allMissing,
568	    bestAgent: bestMatches[0]?.agent || null,
569	    topScore,
570	    canHandle,
571	    recommendation,
572	  });
573	
574	  return {
575	    canHandle,
576	    confidence: topScore,
577	    bestMatches,
578	    gaps: allMissing,
579	    recommendation,
580	    inferredSkills: required,
581	  };
582	}
