588	/**
589	 * Run the weekly Cadence review and write the review file + latest summary.
590	 * Applies all decisions (promotions/PIPs/retirements).
591	 */
592	function runCadenceReview(orgModule, experienceModule, agentRuns) {
593	  const week = currentIsoWeek();
594	  const reviewedAt = new Date().toISOString();
595	
596	  // 1. Refresh experience so decisions use current data
597	  experienceModule.recomputeAllExperience(orgModule);
598	
599	  // 2. Run a Witness sweep first so recommendations are current
600	  runWitnessSweep(orgModule, experienceModule, agentRuns);
601	  const recommendations = dbModule.loadRecommendations();
602	  if (!recommendations.pipCandidates) recommendations.pipCandidates = [];
603	  if (!recommendations.promotionCandidates) recommendations.promotionCandidates = [];
604	
605	  // 3. Apply promotions
606	  const promotions = [];
607	  for (const cand of recommendations.promotionCandidates || []) {
608	    const result = promoteAgent(orgModule, experienceModule, cand.agent);
609	    if (result.ok) promotions.push({ agent: cand.agent, to: result.agent.levelTitle });
610	  }
611	
612	  // 4. Apply PIPs
613	  const pipsOpened = [];
614	  for (const cand of recommendations.pipCandidates || []) {
615	    const result = openPip(orgModule, cand.agent, cand.reasons.join('; '));
616	    if (result.ok) pipsOpened.push({ agent: cand.agent });
617	  }
618	
619	  // 5. Write review file
620	  const review = {
621	    week,
622	    reviewedAt,
623	    director: 'cadence',
624	    promotions,
625	    pipsOpened,
626	    pipsClosed: [],
627	    retirements: [],
628	    newHires: [],
629	    capabilityGaps: dbModule.getRecentGaps(10),
630	    recommendations,
631	  };
632	  dbModule.saveReview(week, review);
633	
634	  // 6. Write human-readable latest.md
635	  const latest = [
636	    `# Cadence Review — ${week}`,
637	    `_${reviewedAt}_`,
638	    '',
639	    `**Promotions:** ${promotions.length}`,
640	    ...promotions.map((p) => `- ${p.agent} → ${p.to}`),
641	    '',
642	    `**PIPs opened:** ${pipsOpened.length}`,
643	    ...pipsOpened.map((p) => `- ${p.agent}`),
644	    '',
645	    `**Recommendations pending:**`,
646	    `- Promotion candidates: ${(recommendations.promotionCandidates || []).length}`,
647	    `- PIP candidates: ${(recommendations.pipCandidates || []).length}`,
648	  ].join('\n');
649	  fs.writeFileSync(path.join(REVIEWS_DIR, 'latest.md'), latest);
650	
651	  return review;
652	}
